-- Wächter Migration 207 (nur lesen). Erwartungen: werkzeuge/m207_md5.json. funktionen = die von 207 geänderten und neuen Funktionen.
SELECT (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_rollen_person_ui_aktion', 'kalender_web_aktion', 'ally_person_speichern', 'kalender_ansicht', 'marketing_posten_ui_aktion'])) AS funktionen;
